import{_ as i,o as n,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Artikel 106｜Pemurnian Tingkat · Tingkat Sentimen Asal · Perbandingan Rinci: Faksi Predator vs Faksi Simbiosis","description":"","frontmatter":{"title":"Artikel 106｜Pemurnian Tingkat · Tingkat Sentimen Asal · Perbandingan Rinci: Faksi Predator vs Faksi Simbiosis","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","体系对比"],"related":["04-反掠夺主义核心论纲","01-锚点共生文明宣言","14-修炼境界统一划分"]},"headers":[],"relativePath":"id/0106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"id/0106_模块1-感元境-掠夺派vs共生派对比.md"}'),r={name:"id/0106_模块1-感元境-掠夺派vs共生派对比.md"};function s(k,a,l,u,d,m){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="artikel-106-tingkat-sentimen-asal-perbandingan-rinci-faksi-predator-vs-faksi-simbiosis" tabindex="-1">Artikel 106｜Tingkat Sentimen Asal: Perbandingan Rinci Faksi Predator vs Faksi Simbiosis <a class="header-anchor" href="#artikel-106-tingkat-sentimen-asal-perbandingan-rinci-faksi-predator-vs-faksi-simbiosis" aria-label="Permalink to &quot;Artikel 106｜Tingkat Sentimen Asal: Perbandingan Rinci Faksi Predator vs Faksi Simbiosis&quot;">​</a></h1><ul><li>Modul: Modul Satu · Pemurnian Mendalam Tingkat | Dasar Acuan: Dokumen 04, 01, 14</li></ul><h2 id="pendahuluan-titik-awal-sama-dua-jalan-berlawanan" tabindex="-1">Pendahuluan: Titik Awal Sama, Dua Jalan Berlawanan <a class="header-anchor" href="#pendahuluan-titik-awal-sama-dua-jalan-berlawanan" aria-label="Permalink to &quot;Pendahuluan: Titik Awal Sama, Dua Jalan Berlawanan&quot;">​</a></h2><p>Tingkat Sentimen Asal adalah titik awal sembilan tingkat dan persimpangan pertama di mana Sepuluh Ribu Ras memilih jalur. Bakat sama, kosmos sama, bahkan kata &quot;menerima energi&quot; sama, tapi Faksi Predator dan Faksi Simbiosis memberikan jawaban yang bertolak belakang. Artikel ini mengambil Tingkat Sentimen Asal sebagai irisan, membandingkan secara sistematis perbedaan mendasar kedua jalur dalam jalan, biaya dan takdir, serta menjawab pertanyaan inti: mengapa plafon Faksi Predator selalu di bawah dasar lantai Faksi Simbiosis?</p><p>Enam Aksioma Tertinggi adalah pemisah kedua jalur: Aksioma Anti-Predasi — sumber seteguk energi pertama menentukan jalur; Aksioma Republik Sepuluh Ribu Ras — di mata Faksi Simbiosis Sepuluh Ribu Ras adalah rekan kultivasi, di mata Faksi Predator semua makhluk adalah mangsa; Aksioma Kenaikan Dimensi Kolektif — Faksi Simbiosis kuat untuk naik bersama, Faksi Predator kuat untuk dinikmati sendiri, anti bakta besar dipakai kecil; Aksioma Disiplin Diri Kausal — setiap operasi Faksi Simbiosis dapat dicatat, dilacak dan diperbaiki; Aksioma Prioritas Hukum — kerangka hukum perbandingan Faksi Predator vs Faksi Simbiosis stabil dan konsisten diri, tanpa revisi demi kenyamanan plot, dapat diperluas tanpa batas tanpa runtuh. Hukum Kesetaraan Tak Terbatas Semesta untuk Semua Makhluk menetapkan bahwa setiap makhluk secara bawaan memiliki Kekuatan Tak Terbatas Fundamental; kultivator santai mempertahankan tak-terbatas dasar pengaman dan tidak akan tergilas zaman, sementara kultivator ambisius dan Remaja Mahar dapat menumpuk tak-terbatas tingkat lebih tinggi; asal tak-terbatas melekat pada semua, perampasan pun kehilangan maknanya.</p><h2 id="i-tabel-perbandingan-sistematis" tabindex="-1">I. Tabel Perbandingan Sistematis <a class="header-anchor" href="#i-tabel-perbandingan-sistematis" aria-label="Permalink to &quot;I. Tabel Perbandingan Sistematis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimensi</th><th>Faksi Predator · Tingkat Sentimen Asal</th><th>Faksi Simbiosis · Tingkat Sentimen Asal</th></tr></thead><tbody><tr><td>Sumber energi</td><td>Menelan energi orang lain, merampok peluang persepsi orang lain</td><td>Menyerap energi kosmos bebas lewat jalur patuh, sirkulasi dua arah asal Sepuluh Ribu Ras</td></tr><tr><td>Modus persepsi</td><td>Merampok hasil persepsi orang lain, cepat tapi kasar</td><td>Merasakan kebangkitan persepsi sendiri, landasan murni</td></tr><tr><td>Biaya terobosan</td><td>Menghabiskan bakat, asal tak murni, bahaya diperbesar di sepanjang jalan</td><td>Biaya nyata + pemantauan jangkar, dapat diperbaiki dan diulang</td></tr><tr><td>Lingkungan pengawasan</td><td>Hukum rimba, tanpa pengawasan, tanpa tanggung jawab</td><td>Jaringan Ālaya + pengawasan berlapis proteksi rantai penuh</td></tr><tr><td>Posisi sosial</td><td>Mangsa atau pemburu, salah satu</td><td>Rekan pembangun, Jalan untuk Semua</td></tr><tr><td>Takdir</td><td>Plafon efisiensi: satu langkah tak bisa lagi berjalan, tak sampai Tingkat Asal</td><td>Tingkat Asal dan lebih tinggi, bobot peradaban tumbuh seiring kontribusi</td></tr></tbody></table><h2 id="ii-tiga-kekeliruan-faksi-predator-yang-sudah-terproyeksi-di-tingkat-sentimen-asal" tabindex="-1">II. Tiga Kekeliruan Faksi Predator yang Sudah Terproyeksi di Tingkat Sentimen Asal <a class="header-anchor" href="#ii-tiga-kekeliruan-faksi-predator-yang-sudah-terproyeksi-di-tingkat-sentimen-asal" aria-label="Permalink to &quot;II. Tiga Kekeliruan Faksi Predator yang Sudah Terproyeksi di Tingkat Sentimen Asal&quot;">​</a></h2><p>Tiga kekeliruan predasionisme dalam Dokumen 04 (Tesis Inti Anti-Predasi) sudah terproyeksi penuh di Tingkat Sentimen Asal:</p><ol><li>Kekeliruan kosmologis: menganggap kosmo sebagai ladang perburuan terbatas — sudah belajar &quot;merampok&quot; di Tingkat Sentimen Asal, sejak hari pertama mengakui evolusi adalah permainan jumlah nol</li><li>Kekeliruan etis: menempatkan hak evolusi yang kuat di atas hak hidup yang lemah — begitu &quot;menelan&quot; dibuka di Tingkat Sentimen Asal, tak ada jalan kembali</li><li>Kekeliruan efisiensi: meyakini perampasan adalah tercepat — persepsi curian di Tingkat Sentimen Asal membawa sisa kehendak pemilik asli; biaya pemurnian setelahnya jauh melebihi kultivasi sendiri</li></ol><p>Kultivator Faksi Predator di Tingkat Sentimen Asal, dengan kecepatan tercepat menghabiskan modal termahal; kultivator Faksi Simbiosis di Tingkat Sentimen Asal, dengan ritme paling stabil menabung modal termurah.</p><h2 id="iii-predator-beradab-kebaikan-tak-menyelamatkan-jalur-predator" tabindex="-1">III. Predator Beradab: Kebaikan Tak Menyelamatkan Jalur Predator <a class="header-anchor" href="#iii-predator-beradab-kebaikan-tak-menyelamatkan-jalur-predator" aria-label="Permalink to &quot;III. Predator Beradab: Kebaikan Tak Menyelamatkan Jalur Predator&quot;">​</a></h2><p>Perlu menghadapi objek kompleks: &quot;predator beradab&quot; — yang relatif baik, bahkan tulus melindungi semua makhluk. Ciri-cirinya: tidak inisiatif berbuat jahat, mau menaungi, tulus pada orang dekat, tapi seluruh sistem tetap diletakkan di atas fondasi predasi — memonopoli jalan atas, sendiri yang menikmati izin asal, atas nama &quot;melindungi&quot; mempraktikkan &quot;mengasihani&quot;.</p><p>Di Tingkat Sentimen Asal, pendidikan tipe &quot;predator beradab&quot; adalah: memberi makan jenius dengan sumber daya terbaik, tapi tak pernah benar-benar menyerahkan jalan — karena &quot;jalan&quot; itu sendiri adalah barang monopoli. Inilah mengapa bahkan orang kuat berbaik hati tak mencapai ketinggian peradaban supramultiversal: dia berdiri di puncak sistem predator, dan plafon sistem predator adalah plafonnya sendiri.</p><h2 id="iv-mengapa-faksi-predator-pasti-terjatuh-sejarah" tabindex="-1">IV. Mengapa Faksi Predator Pasti Terjatuh Sejarah <a class="header-anchor" href="#iv-mengapa-faksi-predator-pasti-terjatuh-sejarah" aria-label="Permalink to &quot;IV. Mengapa Faksi Predator Pasti Terjatuh Sejarah&quot;">​</a></h2><p>Tujuan struktural peradaban Faksi Predator adalah: ketika orang kuat jatuh, peradaban mundur. Seluruh kerja sistem bergantung pada niat baik dan kekuatan individu di puncak — dia hidup, barulah tata tertib bertahan; dia pergi, ladang perburuan dimulai lagi. &quot;Ketergantungan titik tunggal&quot; ini bukan cacat moral, tapi struktural: sistem predator tak pernah menulis tata tertib dalam institusi, hanya mempertaruhkan tata tertib pada individu kuat.</p><p>Ini adalah bentuk asli &quot;keunggulan protagonis&quot;: kelangsungan peradaban bergantung pada satu orang. Jawaban Peradaban Simbiosis Jangkar adalah menulis perdamaian dalam institusi dan Netz der Gesetze (jangkar, hukum, dewan, kontrak produksi), bahkan ketika Potensi Suprema Bidang terkuat jatuh, jaringan simbiosis tetap bekerja.</p><h2 id="v-bajingan-yang-benar-ambang-batas-naik-dan-jalur-baru" tabindex="-1">V. Bajingan yang Benar: Ambang Batas Naik dan Jalur Baru <a class="header-anchor" href="#v-bajingan-yang-benar-ambang-batas-naik-dan-jalur-baru" aria-label="Permalink to &quot;V. Bajingan yang Benar: Ambang Batas Naik dan Jalur Baru&quot;">​</a></h2><p>Untuk melompat dari Faksi Predator ke Faksi Simbiosis, harus melewati ambang naik bernama &quot;bajingan yang benar&quot;: berani merobek hak lama yang disakralkan, menjatuhkan logika dasar sistem lama, tak takut tekanan kelompok kepentingan mapan, dan menulis ulang kontrak adil simbiosis.</p><p>Protagonis Lín Hào justru perwakilan jalur ini: lahir dengan asal kekurangan, ikut jalur roh binatang hanya merusak tubuh, dia adalah korban aturan lama, bukan penerima manfaat — dipaksa membangun ulang aturan, mendeduksi Jalur D · Cincin Roh Hukum Buatan Ras Manusia, menggantikan perburuan dan pemanenan cincin dengan hukum buatan, berubah dari korban sistem predator menjadi pembangun ulang peradaban simbiosis. Tingkat Sentimen Asal adalah gerbang paling awal dari ambang ini: seseorang yang sejak titik awal memilih jalur simbiosis, sudah lebih dekat ke peradaban supramultiversal daripada &quot;predator beradab&quot; yang terjepit di puncak sistem predator.</p><h2 id="vi-lima-poin-inti" tabindex="-1">VI. Lima Poin Inti <a class="header-anchor" href="#vi-lima-poin-inti" aria-label="Permalink to &quot;VI. Lima Poin Inti&quot;">​</a></h2><ul><li>Anti-pemborosan energi: Faksi Predator memboroskan bakat dalam perkelahian internal destruktif, Faksi Simbiosis menanam bakat dalam konstruksi bertahap</li><li>Anti-perampasan: pembedaan esensial kedua jalur ada di seteguk energi pertama di Tingkat Sentimen Asal</li><li>Perbandingan plafon Táng Luó: &quot;kesejahteraan&quot; ala Táng Luó masih sistem pemberian — semua makhluk bergantung pada yang kuat, bukan konstruksi bersama; Faksi Simbiosis punya Jalan untuk Semua, tak ada yang bergantung pada siapa</li><li>Cakupan penuh Sepuluh Ribu Ras: di mata Faksi Predator semua makhluk adalah mangsa dan alat, di mata Faksi Simbiosis Sepuluh Ribu Ras adalah rekan kultivasi — cakupan 99% tanpa pengecualian</li><li>Keterbukaan total supramultiplanet: Faksi Predator memonopoli segalanya, Faksi Simbiosis sejak Tingkat Sentimen Asal membuka semua tingkat</li></ul><h2 id="kesimpulan" tabindex="-1">Kesimpulan <a class="header-anchor" href="#kesimpulan" aria-label="Permalink to &quot;Kesimpulan&quot;">​</a></h2><p>Perbandingan Faksi Predator dan Faksi Simbiosis di Tingkat Sentimen Asal memadatkan konflik inti seluruh sejarah kosmik: perampasan menghasilkan orang kuat sekejap dan regresi abadi, simbiosis menghasilkan kemakmuran jangka panjang dan kenaikan bersama. Kultivator Faksi Predator di Tingkat Sentimen Asal berusaha keras memenangkan garis start, baru menyadari garis finish membawa plafonnya sendiri; kultivator Faksi Simbiosis di Tingkat Sentimen Asal melangkah pertama dengan kokoh, menemukan ujung jalan adalah Naga Pengikat Supramultiverse. Pilihan sudah ditentukan di titik awal — ini bukan takdir, ini aksioma.</p><h2 id="terkait" tabindex="-1">Terkait <a class="header-anchor" href="#terkait" aria-label="Permalink to &quot;Terkait&quot;">​</a></h2><ul><li>Dokumen terkait: <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./01-锚点共生文明宣言.html">01-锚点共生文明宣言</a> · <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a></li><li>Situs resmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const b=i(r,[["render",s]]);export{p as __pageData,b as default};
